    for r in range(9):
        for c in range(9):
            d = board[r][c]
            if d == ".":
                continue
            for k in range(9):
                if k != c and board[r][k] == d:
                    return False
                if k != r and board[k][c] == d:
                    return False
            br, bc = 3 * (r // 3), 3 * (c // 3)
