class BruteForce:
    """Delimiter with backslash escaping: must inspect every character."""

    def encode(self, strs: List[str]) -> str:
        escaped = [s.replace("\\", "\\\\").replace(",", "\\,") for s in strs]
        return ",".join(escaped) + ("," if strs else "")

    def decode(self, s: str) -> List[str]:
        out, cur, i = [], [], 0
        while i < len(s):
            ch = s[i]
            if ch == "\\":
                cur.append(s[i + 1])
                i += 2
            elif ch == ",":
                out.append("".join(cur))
                cur = []
                i += 1
            else:
                cur.append(ch)
                i += 1
        return out

